result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/lod.js", "content": "import * as THREE from 'three';

/**
 * Builds a THREE.LOD ("statue") with three detail levels:
 *   - "high": IcosahedronGeometry detail 3, visible below distance 20
 *   - "mid":  IcosahedronGeometry detail 1, active at distance >= 20
 *   - "low":  IcosahedronGeometry detail 0, active at distance >= 60
 *
 * Per THREE.LOD semantics, thresholds are upper-inclusive: the level
 * becomes active as soon as the camera distance reaches its threshold.
 */
export function buildStatueLOD() {
  const lod = new THREE.LOD();

  const makeMesh = (name, detail) => {
    const mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(1, detail), new THREE.MeshBasicMaterial());
    mesh.name = name;
    return mesh;
  };

  lod.addLevel(makeMesh('high', 3), 0);
  lod.addLevel(makeMesh('mid', 1), 20);
  lod.addLevel(makeMesh('low', 0), 60);

  return lod;
}

/**
 * Determines which LOD level would be visible from a camera placed at
 * (0, 0, distance) looking down the default -Z... i.e. toward origin.
 * Returns the name of the sole visible level object.
 */
export function visibleLevelAt(lod, distance) {
  const camera = new THREE.PerspectiveCamera();
  camera.position.set(0, 0, distance);
  camera.updateMatrixWorld();
  lod.update(camera);

  const visible = lod.children.filter((child) => child.visible);
  if (visible.length !== 1) {
    throw new Error(
      `Expected exactly one visible LOD level at distance ${distance}, got ${visible.length}: ` +
        visible.map((c) => c.name).join(', ')
    );
  }
  return visible[0].name;
}
