result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/lod.test.js", "content": "import { describe, it, expect } from 'vitest';
import { buildStatueLOD, visibleLevelAt } from '../src/lod.js';

describe('buildStatueLOD', () => {
  it('has three levels named high, mid, low with correct geometry detail', () => {
    const lod = buildStatueLOD();
    expect(lod.levels.map((l) => l.object.name)).toEqual(['high', 'mid', 'low']);
    expect(lod.levels.map((l) => l.distance)).toEqual([0, 20, 60]);
    // IcosahedronGeometry vertex counts for detail 3, 1, 0
    const details = lod.levels.map((l) => l.object.geometry.getAttribute('position').count / 5); // 20*4^d faces -> verts/5 unique-ish; just compare relative
    expect(details[0]).toBeGreaterThan(details[1]);
    expect(details[1]).toBeGreaterThan(details[2]);
  });
});

describe('visibleLevelAt', () => {
  let lod;

  beforeEach(() => {
    lod = buildStatueLOD();
  });

  it('yields "high", "mid", "low" at distances 5, 30, 100', () => {
    expect(visibleLevelAt(lod, 5)).toBe('high');
    expect(visibleLevelAt(lod, 30)).toBe('mid');
    expect(visibleLevelAt(lod, 100)).toBe('low');
  });

  it('shows exactly one level at each of 12 sampled distances from 1 to 120', () => {
    for (let i = 1; i <= 12; i++) {
      const distance = Math.round((i / 12) * 120); // 10, 20, ..., 120
      const name = visibleLevelAt(lod, distance);
      expect(['high', 'mid', 'low']).toContain(name);
      const visibleCount = lod.children.filter((c) => c.visible).length;
      expect(visibleCount).toBe(1);
    }
  });

  // Verified empirically against three.js: LOD.update picks the last level
  // whose threshold is <= camera distance (levels scanned far-to-near with
  // distance >= threshold). Thresholds are therefore upper-inclusive:
  // at exactly 20 the "mid" level is already active.
  it('activates "mid" inclusively at exactly distance 20', () => {
    expect(visibleLevelAt(lod, 19.999)).toBe('high');
    expect(visibleLevelAt(lod, 20)).toBe('mid');
    expect(visibleLevelAt(lod, 20.001)).toBe('mid');
  });
});

// vitest needs beforeEach imported
import { beforeEach } from 'vitest';
"})
